package com.example.dsatracker.mapper;import com.example.dsatracker.dto.TagRequestDTO;import com.example.dsatracker.dto.TagResponseDTO;import com.example.dsatracker.model.Tag;public class TagMapper {    private TagMapper() {    }    public static Tag toEntity(TagRequestDTO dto) {        return Tag.builder()                .name(dto.getName())                .description(dto.getDescription())                .build();    }    public static TagResponseDTO toResponse(Tag tag) {        return TagResponseDTO.builder()                .id(tag.getId())                .name(tag.getName())                .description(tag.getDescription())                .build();    }}